package com.leanllm.agentforge;

import java.util.Objects;

/**
 * Immutable execution artifact generated by a subagent task.
 * Captures file output, cryptographic digest, byte size, and verification state.
 *
 * @param artifactId Unique identifier for the output artifact.
 * @param taskId Originating TaskContract ID.
 * @param relativePath Workspace-relative path to the generated or modified file.
 * @param contentDigest SHA-256 hex digest of the file contents.
 * @param sizeBytes Size of the output in bytes.
 * @param verified True if the artifact passed validation or lint checks.
 */
public record ExecutionArtifact(
    String artifactId,
    String taskId,
    String relativePath,
    String contentDigest,
    long sizeBytes,
    boolean verified
) {
    public ExecutionArtifact {
        Objects.requireNonNull(artifactId, "artifactId cannot be null");
        Objects.requireNonNull(taskId, "taskId cannot be null");
        Objects.requireNonNull(relativePath, "relativePath cannot be null");
        Objects.requireNonNull(contentDigest, "contentDigest cannot be null");
    }
}
